  const tier2Gain = this.ctx.createGain();
  tier2Gain.gain.value = 0.0001;

  // Octave-up top: C4 + G4. Brighter sparkle for the white-bullet tier.
  const topC = this.ctx.createOscillator();
  const topG = this.ctx.createOscillator();
  topC.type = "sine";
