1	import type { Game } from "../Game";
2	import { Asteroid } from "../Asteroid";
3	import { Alien } from "../Alien";
4	import { Comet } from "../Comet";
5	import { Bullet } from "../Bullet";
6	import { Vec } from "../vec";
7	import { loseCombo } from "./rhythmGate";
8	import { syncComboHud, syncHud, flashScoreGain } from "./hud";
9	import { popupCombo, popupScore } from "./popups";
10	import {
11	  emitExplosion,
12	  emitCrackParticles,
13	  emitAlienExplosion,
14	  emitCometExplosion,
15	} from "./particleBursts";
16	import { snapshotAsteroidKill, snapshotAlienKill, snapshotCometKill } from "./killSnapshot";
17	import { alignBassBeat } from "./waveDirector";
18	import type { KillBucket } from "./killBuckets";
19	
20	// Why: feeds the leaderboard's per-run breakdown; bucket names stay human-readable for display.
21	const bumpKill = (game: Game, bucket: KillBucket) => {
22	  game.killTally[bucket] = (game.killTally[bucket] ?? 0) + 1;
23	};
24	
25	const asteroidBucket = (a: Asteroid): KillBucket => {
26	  if (a.kind === "boss") return "boss";
27	  if (a.isBass()) return "bassteroid";
28	  if (a.kind === "chime" || a.kind === "bell" || a.kind === "warble" || a.kind === "tink") return a.kind;
29	  return `asteroid_${a.size}`;
30	};
31	
32	// Why: bassteroids run their own bassHit/bassEcho path; this maps the non-bass kinds to sounds.
33	export const hitSoundFor = (
34	  a: Asteroid,
35	): "explosionLarge" | "explosionMedium" | "explosionSmall" | "chime" | "bell" | "warble" | "tink" => {
36	  if (a.kind === "chime") return "chime";
37	  if (a.kind === "bell") return "bell";
38	  if (a.kind === "warble") return "warble";
39	  if (a.kind === "tink") return "tink";
40	  return a.size === "large" ? "explosionLarge" : a.size === "medium" ? "explosionMedium" : "explosionSmall";
41	};
42	
43	// Why: same combo-update rule for every kill type — one helper means callers don't reimplement.
44	//   hitPos anchors the "COMBO LOST" popup at the target the off-beat shot landed on.
45	export const applyHitToCombo = (game: Game, isOnBeatHit: boolean, hitPos: Vec) => {
46	  if (isOnBeatHit && game.beatCombo >= 1) {
47	    game.beatCombo += 1;
48	    if (game.beatCombo > game.maxCombo) game.maxCombo = game.beatCombo;
49	    syncComboHud(game);
50	  } else if (!isOnBeatHit && game.beatCombo !== 0) {
51	    loseCombo(game, hitPos);
52	  }
53	};
54	
55	// Why: multiplier + sparkle + popup are the on-beat reward — one helper guarantees consistency.
56	//   Returns the points actually added so the parade can flash the same "+N" per kill.
57	const awardScoreForKill = (game: Game, hitPos: Vec, baseScore: number, isOnBeatHit: boolean): number => {
58	  let scoreEarned = baseScore;
59	  if (isOnBeatHit) {
60	    const multiplier = game.beatCombo;
61	    scoreEarned = Math.round(scoreEarned * multiplier);
62	    game.sound.play("comboSparkle", 1, hitPos);
63	    if (multiplier >= 2) game.popups.push(popupCombo(hitPos, multiplier));
64	  }
65	  game.score += scoreEarned;
66	  flashScoreGain(game, scoreEarned);
67	  return scoreEarned;
68	};
69	
70	// Why: only medium/small children carry drones (large bass has its own continuous low end).
71	const restartChildBassDrones = (game: Game, children: Asteroid[]) => {
72	  for (const c of children) {
73	    alignBassBeat(game, c);
74	    if (c.size === "medium" || c.size === "small") {
75	      game.sound.startBassteroidDrone(c, c.kind as "bassA" | "bassB" | "bassC" | "bassD", c.size, c.pos);
76	    }
77	  }
78	};
79	
80	// Why: audio-free core lets bullet vs ram paths stage their own kill-sound order independently.
81	//   scoreEarned is captured into the snapshot so the parade can flash "+N" beneath each sprite.
82	const finishAsteroidKillCore = (
83	  game: Game,
84	  a: Asteroid,
85	  killerVel: Vec,
86	  isOnBeatHit: boolean,
87	  scoreEarned: number,
88	): Asteroid[] => {
89	  emitExplosion(game.particles, game.shards, a, isOnBeatHit);
90	  if (a.isBass()) game.sound.stopBassteroidDrone(a);
91	  const asteroidHit = hitSoundFor(a);
92	  const snap = snapshotAsteroidKill(a, a.isBass() ? "bassEcho" : asteroidHit, scoreEarned);
93	  if (snap) game.killedSnapshots.push(snap);
94	  bumpKill(game, asteroidBucket(a));
95	  const children = a.split(killerVel);
96	  if (a.isBass()) restartChildBassDrones(game, children);
97	  return children;
98	};
99	
100	// Why: bassEcho → asteroidHit order matches the original handleCollisions bullet branch.
101	export const onAsteroidKilledByBullet = (
102	  game: Game,
103	  a: Asteroid,
104	  b: Bullet,
105	  isOnBeatHit: boolean,
106	): Asteroid[] => {
107	  const scoreEarned = awardScoreForKill(game, b.pos, a.scoreValue(), isOnBeatHit);
108	  if (a.isBass()) game.sound.play("bassEcho", 1, a.pos);
109	  game.sound.play(hitSoundFor(a), 1, a.pos);
110	  return finishAsteroidKillCore(game, a, b.vel, isOnBeatHit, scoreEarned);
111	};
112	
113	// Why: asteroidHit → bassEcho (reverse of bullet path) preserves the original ram-branch order.
114	// Why: ram kills award no points — pass 0 so the parade flash reflects the actual payout.
115	export const onAsteroidKilledByRam = (game: Game, a: Asteroid, shipVel: Vec): Asteroid[] => {
116	  if (a.isBass()) game.sound.play("bassHit", 1, a.pos);
117	  game.sound.play(hitSoundFor(a), 1, a.pos);
118	  if (a.isBass()) game.sound.play("bassEcho", 1, a.pos);
119	  return finishAsteroidKillCore(game, a, shipVel, false, 0);
120	};
121	
122	// Why: bassteroids take multiple hits to kill; chip points keep the player rewarded for
123	// every rhythm-good hit along the way, not just the kill shot.
124	const bassChipScore = (a: Asteroid): number => Math.max(1, Math.round(a.scoreValue() / 4));
125	
126	// Why: bullet crack — bassHit announces the chip; sparkle layers on if it was on-beat.
127	// Bassteroid chips also pay out (small) points + combo popup so multi-hit kills feel rewarding.
128	export const onAsteroidCrackedByBullet = (game: Game, a: Asteroid, b: Bullet, isOnBeatHit: boolean) => {
129	  if (a.isBass()) game.sound.play("bassHit", 1, a.pos);
130	  emitCrackParticles(game.particles, a, isOnBeatHit);
131	  if (isOnBeatHit) game.sound.play("comboSparkle", 1, b.pos);
132	  if (a.isBass()) awardScoreForKill(game, b.pos, bassChipScore(a), isOnBeatHit);
133	};
134	
135	// Why: ram crack uses asteroidHit (not bassHit) so the impact reads as a kick, not a chip.
136	export const onAsteroidCrackedByRam = (game: Game, a: Asteroid) => {
137	  game.sound.play(a.isBass() ? "bassHit" : hitSoundFor(a), 1, a.pos);
138	  emitCrackParticles(game.particles, a, false);
139	};
140	
141	// Why: no split path here — alien deaths fall into the "single body, fixed sound" pattern.
142	export const onAlienKilled = (game: Game, al: Alien, b: Bullet, isOnBeatHit: boolean) => {
143	  const scoreEarned = awardScoreForKill(game, b.pos, al.scoreValue, isOnBeatHit);
144	  game.shake = Math.min(game.shake + 0.5, 1.4);
145	  game.sound.play("alienExplode", 1, al.pos);
146	  game.sound.stopAlienDrone(al);
147	  emitAlienExplosion(game.particles, al);
148	  const snap = snapshotAlienKill(al, "alienExplode", scoreEarned);
149	  if (snap) game.killedSnapshots.push(snap);
150	  bumpKill(game, `alien_${al.size}`);
151	};
152	
153	// Why: shared cracked-alien feedback for medium/big saucers since the killing-hit path differs.
154	export const onAlienCracked = (game: Game, isOnBeatHit: boolean, pos: Vec) => {
155	  game.sound.play("alienHit", 1, pos);
156	  game.shake = Math.min(game.shake + 0.18, 1.2);
157	  if (isOnBeatHit) game.sound.play("comboSparkle", 1, pos);
158	};
159	
160	// Why: comets pay a flat 5000 base; combo multiplier and a "+N" readout match the rest of the
161	// scoring system so the player sees the payout and any rhythm bonus at the kill site.
162	export const onCometKilled = (game: Game, c: Comet, b: Bullet, isOnBeatHit: boolean) => {
163	  const baseScore = 5000;
164	  const scoreEarned = isOnBeatHit ? Math.round(baseScore * game.beatCombo) : baseScore;
165	  game.score += scoreEarned;
166	  flashScoreGain(game, scoreEarned);
167	  game.popups.push(popupScore(b.pos, scoreEarned));
168	  if (isOnBeatHit) {
169	    game.sound.play("comboSparkle", 1, b.pos);
170	    if (game.beatCombo >= 2) game.popups.push(popupCombo(b.pos, game.beatCombo));
171	  }
172	  game.shake = Math.min(game.shake + 0.6, 1.6);
173	  game.sound.play("cometDestroyed", 1, c.pos);
174	  game.sound.stopCometShimmer(c);
175	  emitCometExplosion(game.particles, c);
176	  const snap = snapshotCometKill(c, "cometDestroyed", scoreEarned);
177	  if (snap) game.killedSnapshots.push(snap);
178	  bumpKill(game, "comet");
179	  syncHud(game);
180	};
