1	import type { Game } from "../Game";
2	import { Ship } from "../Ship";
3	import { spawnAsteroidAtEdge, BASS_KINDS } from "../Asteroid";
4	import { ParticleSystem } from "../Particle";
5	import { v } from "../vec";
6	import { BEAT_WINDOW } from "./rhythmConstants";
7	import { syncHud, syncComboHud, syncPowerupHud } from "./hud";
8	import { comboGrid } from "./rhythmGate";
9	import { spawnWave, updateBgBeatIntensity } from "./waveDirector";
10	import { newWaveEventSchedule } from "./waveEvents";
11	import { stopParade } from "./killedParade";
12	import { renderKilledRow } from "./killedParade";
13	import { emitShipDebris } from "./particleBursts";
14	import { hideScoreEntry, showLeaderboard, showScoreEntry } from "./scoreEntry";
15	
16	// Why: Fisher-Yates over Array.sort — sort's randomness is biased and varies across engines.
17	const shuffled = <T,>(arr: ReadonlyArray<T>): T[] => {
18	  const out = arr.slice();
19	  for (let i = out.length - 1; i > 0; i--) {
20	    const j = Math.floor(Math.random() * (i + 1));
21	    [out[i], out[j]] = [out[j], out[i]];
22	  }
23	  return out;
24	};
25	
26	// Why: title screen needs visible motion; decorative rocks don't carry HP or split logic.
27	const spawnTitleDecorativeAsteroids = (game: Game) => {
28	  const decorativeAsteroidIndices = [0, 1, 2, 3, 4];
29	  for (const _ of decorativeAsteroidIndices) {
30	    game.asteroids.push(spawnAsteroidAtEdge(game.w, game.h));
31	  }
32	};
33	
34	// Why: drone loops can outlive a wave — every state-leaver calls this to avoid stale audio.
35	const stopAllPersistentAudio = (game: Game) => {
36	  game.sound.stopAllAlienDrones();
37	  game.sound.stopAllBassteroidDrones();
38	  game.sound.stopAllCometShimmers();
39	  game.sound.stopHaloAmbient();
40	  game.comets = [];
41	};
42	
43	// Why: lifecycle transitions have their own cues; the loseCombo wrrr would just clutter them.
44	const clearComboSilently = (game: Game) => {
45	  game.beatCombo = 0;
46	  game.firedOffBeatSinceLastBeat = false;
47	  syncComboHud(game);
48	};
49	
50	// Why: carries the prior run's trophy lineup so a returning player still sees what they took down.
51	export const showTitle = (game: Game) => {
52	  game.betaMode = false;
53	  game.state = "title";
54	  game.overlayTitleEl.textContent = "Pulsar";
55	  game.overlayStartEl.innerHTML = 'press <span class="key">enter</span> to begin';
56	  game.overlayEl.classList.remove("hidden");
57	  renderKilledRow(game);
58	  clearComboSilently(game);
59	  game.asteroids = [];
60	  game.canisters = [];
61	  stopAllPersistentAudio(game);
62	  game.aliens = [];
63	  game.alienBullets = [];
64	  game.waveEvents = newWaveEventSchedule();
65	  game.slowMoTimer = 0;
66	  game.sound.bgBeatIntensity = 0;
67	  game.pulsar.setBossPlanetState("idle");
68	  spawnTitleDecorativeAsteroids(game);
69	  game.ship.tridentActive = false;
70	  game.ship.rapidActive = false;
71	  game.ship.pierceActive = false;
72	  game.ship.shieldActive = false;
73	  game.ship.radarActive = false;
74	  syncPowerupHud(game);
75	  hideScoreEntry(game);
76	  showLeaderboard(game);
77	};
78	
79	// Why: per-run randomised bass intro order means the wave-2/3 picks vary between runs.
80	export const startGame = (game: Game) => {
81	  game.sound.resume();
82	  game.betaMode = false;
83	  game.state = "playing";
84	  game.score = 0;
85	  game.wave = 1;
86	  game.lives = 3;
87	  resetRunTimers(game);
88	  resetRunCollections(game);
89	  game.bassOrder = shuffled(BASS_KINDS);
90	  game.particles = new ParticleSystem();
91	  game.ship = new Ship(v(game.w / 2, game.h / 2));
92	  game.ship.invuln = 2.0;
93	  game.pulsar.setBossPlanetState("idle");
94	  game.pulsar.setWaveLevel(game.wave);
95	  updateBgBeatIntensity(game);
96	  spawnWave(game);
97	  game.overlayEl.classList.add("hidden");
98	  hideScoreEntry(game);
99	  game.leaderboardEl.classList.add("hidden");
100	  syncHud(game);
101	};
102	
103	// Why: run-scoped state only; spawnWave handles per-wave timers separately.
104	const resetRunTimers = (game: Game) => {
105	  game.beatTime = 0;
