200	  // True while any comet is on screen — slides the pad's "third voice" from
201	  // major-third E4 (bright over the C-major bass bed) down to minor-third
202	  // Eb4, which is consonant with the comet's phrygian dissonance instead of
203	  // fighting it.
204	  haloAmbientCometMode = false;
205	  toneEngine: ToneEngineNodes | null = null;
206	
207	  // Listener position (ship). Pan + distance falloff are computed relative
208	  // to this. Half-width/half-height scale the screen so pan saturates at the
209	  // edges; updated by the game on resize. Listener defaults to screen center
210	  // so positional sounds before the first setListener() still pan sensibly.
211	  listenerX = 0;
212	  listenerY = 0;
213	  halfW = 1;
214	  halfH = 1;
215	  // Subtle spatial profile: pan saturates at ~60% of full L/R, and volume
216	  // drops to ~50% by the screen edge.
217	  private static readonly PAN_MAX = 0.6;
218	  private static readonly DIST_MIN_GAIN = 0.5;
219	
220	  // Tell the audio bus where the listener (ship) is and how big the screen is.
