/* Pilot's Log unlock toast — astronaut-radio aesthetic that matches the
   scratchy vocal cue it announces. Fixed top-center, mono spacing so it
   reads as a transmission rather than a UI element. */
#pilot-log-toast {
  position: fixed;
  top: 22%;
  left: 50%;
  transform: translate(-50%, -6px);
  padding: 10px 18px;
  font-family: "Space Mono", "JetBrains Mono", ui-monospace, monospace;
  font-size: 13px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ffd86a;
  background: rgba(8, 14, 22, 0.78);
  border: 1px solid rgba(255, 216, 106, 0.55);
  border-radius: 2px;
  box-shadow: 0 0 22px rgba(255, 200, 80, 0.35), inset 0 0 10px rgba(255, 200, 80, 0.15);
  text-shadow: 0 0 10px rgba(255, 200, 80, 0.75);
  opacity: 0;
  pointer-events: none;
  z-index: 50;
  transition: opacity 0.35s ease-out, transform 0.35s ease-out;
}

